mapper.select:

		SELECT pfi,FILTER_NUMBER, FILTER_TYPE, CONDITION_ID,FIELD_NAME,CONDITION,NVL(VALUE,'') VALUE,NVL(OPERATOR,' ') OPERATOR, FILTER_FLAG_ACTIVE FROM   NYEHMS_PROCESS_FILTER_VW where 
		FILTER_FLAG_ACTIVE ='Y' and PFI in 

            	#{pfi}



        	and

				FILTER_TYPE in 

			            #{filterType}




        	and

				FILTER_NUMBER in 

			            #{filterNumber}

			   order by FILTER_TYPE, FILTER_NUMBER , OPERATOR DESC
